import {escapeHTML as esc,money,ProductImage,emptyState} from './components.js';
import {installRussianPhone,russianDigits} from './russian-phone.js';

export function checkoutItems(products,cart){return cart.map(item=>{const product=products.find(p=>p.id===item.id&&!p.isMock);return product?{product,quantity:Math.max(1,Math.min(10,Math.floor(item.quantity)||1))}:null;}).filter(Boolean);}
export const checkoutTotal=items=>items.reduce((sum,item)=>sum+item.product.price*item.quantity,0);
function summaryHTML(items){return `<div class="order-lines">${items.map(({product:p,quantity:q})=>`<article class="order-line">${ProductImage(p.images[0],{className:'order-thumb'})}<div><a href="/product/${esc(p.slug)}"><strong>${esc(p.brand)}</strong><span>${esc(p.model)}</span></a><p>${money(p.price)} за шт.</p><label class="order-quantity">Количество<input type="number" data-order-quantity="${esc(p.id)}" min="1" max="10" step="1" value="${q}" aria-label="Количество: ${esc(p.brand+' '+p.model)}"></label><button type="button" class="text-button" data-order-remove="${esc(p.id)}">Убрать</button></div><strong>${money(p.price*q)}</strong></article>`).join('')}</div><div class="order-total"><span>Стоимость очков</span><strong>${money(checkoutTotal(items))}</strong></div><p class="order-note">Наличие моделей, способ оплаты и стоимость доставки подтвердит салон по телефону. Сумма указана без доставки.</p>`;}
export function checkoutPageHTML(products,cart=[]){
 const items=checkoutItems(products,cart);
 return `<section class="checkout-page wrap"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="/catalog">Каталог</a><span>/</span><span>Заявка на покупку</span></nav><header class="checkout-heading"><p class="eyebrow">ВАШ ВЫБОР</p><h1>Оформить заявку</h1><p>Оставьте телефон — Эдуард свяжется с вами и поможет оформить покупку.</p></header><div id="checkout-content">${!items.length?emptyState('Вы ещё не выбрали очки','Добавьте понравившиеся модели из каталога.'): `<div class="checkout-layout"><form id="order-form"><fieldset><legend>Покупатель</legend><div class="checkout-fields"><label>Имя и фамилия<input name="name" autocomplete="name" required maxlength="80" placeholder="Как к вам обращаться"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" required placeholder="+7 (___) ___-__-__"></label></div></fieldset><fieldset><legend>Как получить очки</legend><div class="delivery-options"><label><input type="radio" name="method" value="pickup" checked>Самовывоз из салона</label><label><input type="radio" name="method" value="delivery">Доставка</label></div><p id="pickup-address">Москва, Лермонтовский проспект, 19, корпус 1, ТЦ «Феникс», 1 этаж.</p><div id="delivery-fields" class="checkout-fields" hidden><label>Город<input name="city" autocomplete="address-level2" maxlength="100" placeholder="Ваш город" disabled></label><label>Индекс <small>необязательно</small><input name="postal" autocomplete="postal-code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" disabled></label><label class="checkout-wide">Адрес доставки<input name="address" autocomplete="street-address" maxlength="250" placeholder="Улица, дом, квартира" disabled></label><p class="checkout-wide order-note">Возможность и условия доставки уточним по телефону.</p></div></fieldset><label>Комментарий <small>необязательно</small><textarea name="comment" rows="4" maxlength="1000" placeholder="Удобное время для звонка или вопросы по выбранным очкам"></textarea></label><label class="booking-consent order-consent"><input type="checkbox" name="consent" required><span>Даю согласие ИП Ким Эдуард Олегович на обработку имени, телефона и указанных данных доставки для связи со мной и обработки этой заявки.</span></label><p id="order-message" role="status" aria-live="polite"></p><button class="button" id="send-order" type="submit" disabled>Отправить заявку</button><p class="order-note">Онлайн-оплата не требуется. Отправка заявки не подтверждает наличие очков или доставку.</p></form><aside class="order-summary" aria-labelledby="order-summary-title"><h2 id="order-summary-title">Ваш заказ</h2><div id="order-summary-body">${summaryHTML(items)}</div><a class="text-button" href="/catalog">Продолжить выбор очков</a></aside></div>`}</div></section>`;
}

export function mountCheckout(root,products,store,{fetcher=fetch}={}){
 const form=root.querySelector('#order-form');if(!form)return {refresh(){},dispose(){}};
 const message=root.querySelector('#order-message'),send=root.querySelector('#send-order'),summary=root.querySelector('#order-summary-body');
 const validatePhone=installRussianPhone(form.elements.phone);
 let ready=false,busy=false,active=true,submitted=false,requestId=null;
 function refresh(){if(!active||submitted)return;const items=checkoutItems(products,store.getCart());summary.innerHTML=summaryHTML(items);summary.querySelectorAll('button,input').forEach(el=>el.disabled=busy);send.disabled=!ready||busy||!items.length;}
 function methodChanged(){const delivery=form.elements.method.value==='delivery';root.querySelector('#delivery-fields').hidden=!delivery;root.querySelector('#pickup-address').hidden=delivery;for(const name of ['city','address','postal']){form.elements[name].disabled=!delivery;form.elements[name].required=delivery&&name!=='postal';}}
 form.addEventListener('change',event=>{if(event.target.name==='method')methodChanged();requestId=null;});
 form.addEventListener('input',()=>{if(!busy)requestId=null;});
 summary.addEventListener('change',event=>{if(event.target.dataset.orderQuantity){store.setQuantity(event.target.dataset.orderQuantity,event.target.value);requestId=null;refresh();}});
 summary.addEventListener('click',event=>{const button=event.target.closest('[data-order-remove]');if(button&&!busy){store.removeFromCart(button.dataset.orderRemove);requestId=null;refresh();}});
 const check=async()=>{message.textContent='Проверяем приём заявок…';try{const r=await fetcher('/api/orders/status',{cache:'no-store',signal:AbortSignal.timeout(12000)});const result=await r.json();if(!active)return;ready=r.ok&&result.ready;message.textContent=ready?'':'Приём заявок временно недоступен. Позвоните нам: +7 (495) 641-66-76.';}catch{if(active)message.textContent='Не удалось связаться с сайтом. Обновите страницу или позвоните: +7 (495) 641-66-76.';}finally{refresh();}};
 form.addEventListener('submit',async event=>{
  event.preventDefault();if(busy||!ready)return;validatePhone();if(!form.reportValidity())return;
  const items=checkoutItems(products,store.getCart());if(!items.length)return;
  const values=new FormData(form);requestId ||= crypto.randomUUID();
  const payload={request_id:requestId,customer_name:String(values.get('name')).trim(),customer_phone:'+7'+russianDigits(values.get('phone')),accepted:values.get('consent')==='on',selected_items:items.map(({product,quantity})=>({id:product.id,quantity})),delivery_details:values.get('method')==='delivery'?{method:'delivery',city:values.get('city'),address:values.get('address'),postal:values.get('postal')||''}:{method:'pickup'},customer_comment:String(values.get('comment')||'').trim()};
  busy=true;message.textContent='Отправляем заявку…';form.querySelectorAll('input,textarea,button').forEach(el=>el.disabled=true);refresh();
  try{
   const response=await fetcher('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(20000)});const result=await response.json();
   if(!response.ok)throw Error(result.error||'Не удалось отправить заявку. Попробуйте ещё раз или позвоните в салон.');
   submitted=true;
   for(const item of items){const current=store.getCart().find(c=>c.id===item.product.id);if(current){if(current.quantity>item.quantity)store.setQuantity(current.id,current.quantity-item.quantity);else store.removeFromCart(current.id);}}
   if(!active)return;
   root.querySelector('#checkout-content').innerHTML=`<div class="order-success" role="status"><p class="eyebrow">ЗАЯВКА ПОЛУЧЕНА</p><h2>Спасибо! Мы свяжемся с вами.</h2><p>Эдуард позвонит по указанному номеру, уточнит наличие очков и согласует покупку.</p><p>Номер заявки: <strong>${esc(String(result.id).slice(0,8).toUpperCase())}</strong></p><p>Стоимость выбранных очков: <strong>${money(result.total)}</strong>. Доставка согласуется отдельно.</p><a class="button" href="/catalog">Вернуться в каталог</a></div>`;
  }catch(error){if(active)message.textContent=error.name==='TimeoutError'?'Сервер не ответил вовремя. Повторите отправку: повторная заявка не создаётся.':error.message;}
  finally{busy=false;if(active&&!submitted){form.querySelectorAll('input,textarea,button').forEach(el=>el.disabled=false);methodChanged();refresh();}}
 });
 methodChanged();check();return {refresh,dispose(){active=false;}};
}
